mapper.select:
SELECT g.*, s.name AS store_name
FROM ecom_fba_ledger g
LEFT JOIN ecom_store s ON s.id = g.store_id

    g.store_id = #{storeId}
    AND g.event_type = #{eventType}
    AND g.event_date >= #{beginDate}
    AND g.event_date <= #{endDate}

        AND (g.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR g.fnsku LIKE CONCAT('%', #{keyword}, '%')
             OR g.reference_id LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY g.event_date DESC, g.id DESC

SELECT * FROM ecom_fba_ledger
WHERE store_id = #{storeId} AND event_type = 'Adjustments' AND event_date >= #{since}
  AND reason IN #{r}
ORDER BY event_date, id
